/* Picks the best candidate moby from the moby's list by heading and distance.
 * Exact since tools/ps2eeas_nops.py puts the hazard nop after the shared bc1fl's label. */
char *select_blarg_bombthrower_waypoint(char *moby) {
    short *t = batalia_moby_groups[(unsigned char)moby[0x21]];
    char *best;
    char *p;
    float bestD, bestA;
    int idx;
    char *base;
    if (t == 0) return 0;
    best = 0;
    idx = *(unsigned short *)t & 0x7FFF;
    p = batalia_mobys + (idx << 8);
    bestA = 0.0f;
    bestD = bestA;
    for (;;) {
        if (*(short *)(p + 0xA6) != 0x14D && *(unsigned char *)(p + 0xBC) == 0) {
            float ang, d, a;
            a = fast_atan2(*(float *)(p + 0x10) - *(float *)(moby + 0x10),
                                  *(float *)(p + 0x14) - *(float *)(moby + 0x14));
            base = hero_globals_base + 0xE1D;
            ang = FastDiffRots(a, fast_atan2(*(float *)(base + 0x80) - *(float *)(moby + 0x10),
                                                     *(float *)(base + 0x84) - *(float *)(moby + 0x14)));
            d = FastVecDist(moby + 0x10, p + 0x10);
            if (ang < 1.5707964f) {
                if (bestA < ang) {
                    best = p;
                    bestD = d;
                    bestA = ang;
                }
            } else if ((d >= 16.0f && (d < bestD || bestD < 16.0f)) || (d < 16.0f && bestD < d)) {
                best = p;
                bestD = d;
                bestA = ang;
            }
        }
        if (*t < -1) return best;
        t++;
        idx = *(unsigned short *)t & 0x7FFF;
        p = batalia_mobys + (idx << 8);
    }
}
