/* Update function of the blarg bomb thrower: hit reactions, then a state machine that walks to its bomb crate, picks up and throws bombs at the hero. */
void blarg_bombthrower_update(Moby *moby) {
    Data_DBF68 *d = (Data_DBF68 *)moby->pvars;
    Look_DBF68 look;
    float v50[4];
    float v60[4];
    float v70[4];
    int hit;
    float damage;
    float out;
    Moby *target;
    Moby *old;

    damage = 0.0f;
    Manipulator_ApplyScale_x(moby, batalia_bombthrower_scale, 3.0f, d->blk160);
    if (moby->visible != 0) {
        if (FastVecDist(&moby->pos, batalia_hero_pos) < 29.0f) {
            set_ground_height_band(moby);
            moby->shadow_range = 0x17;
        }
    }
    if (moby->state == 3) {
        moby->flags &= 0xFBFF;
    } else {
        moby->flags |= 0x400;
    }
    if (moby->state == 100) {
        float t = IntToFloat(batalia_bombthrower_fade_ticks);
        int c = d->s132;
        moby->alpha = truncate_float_to_s32_r2((float)c + (float)-c * ((float)(batalia_bombthrower_fade_ticks - d->s130) / t));
        spawn_moby_table_puff_pattern(moby);
        return;
    }
    damage_2D5FA8(moby, find_2D5FA8(moby, 0x330000, 0), &d->health, 0, &hit, &damage, 0, 4);
    if (hit != 1 && moby->state != 0x63) {
        moby->flags |= 0x1000;
        d->health -= damage;
        if (0.0f < d->health) {
            if (damage < 1.0f) {
                d->tint = 100;
            } else {
                char *base;
                d->f80 = g_frame_time_sq * 30.0f;
                d->f88 = g_frame_time * 5.0f;
                d->f8C = g_frame_time * 7.0f;
                d->i94 = 9;
                d->f84 = 0.0005f;
                d->bAD = 0;
                base = hero_globals_base + 0xE1D;
                InitKnockback(moby, d->blk70,
                                  fast_atan2(moby->pos.x - *(float *)(base + 0x80),
                                                    moby->pos.y - *(float *)(base + 0x84)),
                                  6, 1, 0);
                d->fC0 = 6.0f;
                d->fC4 = 10.0f;
                d->tint = 0x78;
                moby->state = 0x5A;
            }
        } else {
            char *base;
            d->i94 = 9;
            d->f84 = 0.0005f;
            d->f80 = g_frame_time_sq * 30.0f;
            d->f88 = batalia_bombthrower_knockback_speed * g_frame_time;
            d->f8C = batalia_bombthrower_knockback_lift * g_frame_time;
            d->bAD = 0;
            base = hero_globals_base + 0xE1D;
            InitKnockback(moby, d->blk70,
                              fast_atan2(moby->pos.x - *(float *)(base + 0x80),
                                                moby->pos.y - *(float *)(base + 0x84)),
                              9, 1, 0);
            d->fC0 = 6.0f;
            d->fC4 = 10.0f;
            explode_2D5FA8(moby, 0, -1);
            d->tint = 0xFA;
            moby->state = 0x63;
            moby->flags &= 0xEFFF;
            d->p120->command = 0;
        }
        effects_start_2D5FA8(moby, d->anim);
    }
    moby->hit_slot = 0xFF;
    look.r44 = FindNearestTargetMoby(moby, 16.0f, &look);
    if (look.target == 0) {
        look.target = *(Moby **)(hero_globals_base + 0x2E9D);
    }
    target = look.target;
    switch (moby->state) {
    case 0:
        moby->flags |= 0x1000;
        d->b29 = 1;
        d->health = 2.0f;
        MoveCtl_Init(d->blkD0);
        d->fDC = 2.0f;
        d->fD8 = 2.0f;
        d->f10C = 0.03f;
        d->f110 = 0.3f;
        d->f114 = 0.25f;
        d->fF4 = batalia_bombthrower_walk_speed_max * g_frame_time;
        d->b58 = truncate_float_to_s32_r2(17.0f);
        d->b5A = truncate_float_to_s32_r2(10.4f);
        clear_u64_value(d->v40);
        d->p120 = (Moby *)select_blarg_bombthrower_waypoint((char *)moby);
        d->p120->command = 1;
        d->i128 = scale_ticks(0xB4);
        if (moby->prev_seq != 4) {
            animate_2D5FA8(moby, 4, 0, 0);
        }
        moby->state = 1;
        d->i134 = scale_ticks(0xF0);
        break;
    case 1:
        ClassifyTargetInCone((char *)moby, d->blkD0, (float *)&d->p120->pos, (char *)d->v40);
        if (FastVecDist(&moby->pos, &d->p120->pos) < 3.0f) {
            if (FastDiffRots(moby->rot.z,
                              fast_atan2(d->p120->pos.x - moby->pos.x,
                                                d->p120->pos.y - moby->pos.y)) < 0.2617994f) {
                if (6.0f < vec_distance_xy(&moby->pos, &target->pos)) {
                    if (moby->prev_seq != 5) {
                        animate_2D5FA8(moby, 5, 0, 10);
                    }
                    moby->state = 6;
                    break;
                }
                d->i134 = scale_ticks(0xF0);
                {
                    Moby *o = d->p120;
                    Moby *n = (Moby *)select_blarg_bombthrower_waypoint((char *)moby);
                    d->p120 = n;
                    if (n == 0) {
                        d->p120 = o;
                    }
                    o->command = 0;
                    d->p120->command = 1;
                }
                break;
            }
        }
        if (fast_dec_timer(&d->i134) != 0) {
            old = d->p120;
            if ((d->p120 = (Moby *)select_blarg_bombthrower_waypoint((char *)moby)) == 0) {
                d->p120 = old;
            }
            old->command = 0;
            d->p120->command = 1;
            d->i134 = scale_ticks(0xF0);
        }
        break;
    case 6:
        ClassifyTargetInCone((char *)moby, d->blkD0, (float *)&d->p120->pos, (char *)d->v40);
        if (moby->anim_flags & 2) {
            animate_2D5FA8(d->p120, 1, 0, scale_ticks(6));
            qcopy(&moby->pos, &d->p120->pos);
            moby->pos.z -= 0.1f;
            if (moby->prev_seq != 1) {
                animate_2D5FA8(moby, 1, 0, 10);
            }
            moby->state = 3;
            moby->flags &= 0xEFFF;
            moby->rot.z = fast_atan2(target->pos.x - moby->pos.x, target->pos.y - moby->pos.y);
            d->i128 = scale_ticks(0x78);
            moby->collision = 0;
        }
        break;
    case 3: {
        float dist = vec_distance_xy(&moby->pos, &target->pos);
        MobySpringTurn_x(fast_atan2(target->pos.x - moby->pos.x, target->pos.y - moby->pos.y),
                            moby, d->blk12C, 0.02f, 0.3f, 0.2f);
        if (dist < 20.0f && 8.0f < dist && fast_dec_timer(&d->i128) != 0) {
            Cam_DBF68 *cam = &batalia_player_camera_c;
            if (FastDiffRots(cam->f158, fast_atan2(moby->pos.x - cam->x, moby->pos.y - cam->y)) < 0.55850536f) {
                goto attack;
            }
        }
        if (d->i38 == 0 || !(0.5f < dist)) {
            break;
        }
    attack:
        animate_2D5FA8(d->p120, 1, 0, scale_ticks(6));
        if (moby->prev_seq != 2) {
            animate_2D5FA8(moby, 2, 0, scale_ticks(7));
        }
        moby->state = 4;
        moby->flags |= 0x1000;
        moby->collision = moby->pclass->collision;
        break;
    }
    case 4:
        v50[0] = FastCos(moby->rot.z) * 2.0f;
        v50[1] = FastSin(moby->rot.z) * 2.0f;
        v50[2] = 0.0f;
        FastVecAdd(v50, v50, &d->p120->pos);
        if (0.2f < vec_distance_xy(&moby->pos, v50)) {
            ClassifyTargetInCone((char *)moby, d->blkD0, v50, (char *)d->v40);
        }
        if (moby->anim_flags & 2) {
            Cam_DBF68 *cam;
            if (vec_distance_xy(&moby->pos, &target->pos) < 6.0f
                || (cam = &batalia_player_camera_c,
                    0.55850536f < FastDiffRots(cam->f158, fast_atan2(moby->pos.x - cam->x, moby->pos.y - cam->y)))) {
                old = d->p120;
                if ((d->p120 = (Moby *)select_blarg_bombthrower_waypoint((char *)moby)) == 0) {
                    d->p120 = old;
                }
                old->command = 0;
                d->p120->command = 1;
                if (moby->prev_seq != 4) {
                    animate_2D5FA8(moby, 4, 0, scale_ticks(7));
                }
                moby->state = 1;
                d->i134 = scale_ticks(0xF0);
            } else {
                if (moby->prev_seq != 3) {
                    animate_2D5FA8(moby, 3, 0, scale_ticks(6));
                }
                moby->state = 5;
            }
        }
        break;
    case 5:
        MobySpringTurn_x(fast_atan2(target->pos.x - moby->pos.x, target->pos.y - moby->pos.y),
                            moby, d->blk12C, 0.02f, 0.3f, 0.2f);
        if (moby->seq == moby->prev_seq && MobyGetFrameValue_x(moby) == 19.0f) {
            float len, t;
            char *p;
            FastVecSub(v70, &target->pos, &moby->pos);
            v70[2] = 0.0f;
            len = FastVecLength(v70);
            t = len / multiply_global_factor(batalia_bombthrower_throw_speed);
            len = len - (batalia_bombthrower_throw_short_rate * t + 2.0f);
            if (10.0f < len) {
                len = 10.0f;
            } else if (len < 3.0f) {
                len = 3.0f;
            }
            ClampVectorLength(v70, len);
            FastVecAdd(v70, v70, &moby->pos);
            Moby_GetJointWorldPos_r2(moby, 9, v50);
            FastVecSub(v60, &target->pos, v50);
            vec_set_length_xy(v60, v60, t);
            v60[2] = jump_speed_4318(v50, v70, &out, t, -(g_frame_time_sq * 15.0f));
            p = spawn_bomb_with_velocity((int)moby, (char *)v50, (char *)v60);
            d->p124 = (Moby *)p;
            if (p != 0) {
                char *pd = ((char *)((Moby *)p)->pvars);
                *(int *)(pd + 0x20) = scale_ticks(0xB4);
                *(short *)(pd + 0xC) = scale_ticks(10);
                *(short *)(pd + 0xE) = scale_ticks(10);
                d->p124->state = 1;
                d->p124->command |= 3;
                d->i128 = scale_ticks(0xB4);
            }
            break;
        }
        if (moby->anim_flags & 2) {
            moby->state = 1;
            if (moby->prev_seq != 4) {
                animate_2D5FA8(moby, 4, 0, 3);
            }
            d->i134 = scale_ticks(0xF0);
        }
        break;
    case 0x5B:
        if (moby->anim_flags & 2) {
            if (moby->prev_seq != 7) {
                animate_2D5FA8(moby, 7, 0, 3);
            }
            moby->state = 0x5D;
        }
        break;
    case 0x5A:
    case 0x5C:
    case 0x5D:
        if (mine_fall(moby, d->blk70) & 0x40) {
            old = d->p120;
            if ((d->p120 = (Moby *)select_blarg_bombthrower_waypoint((char *)moby)) == 0) {
                d->p120 = old;
            } else {
                old->command = 0;
                d->p120->command = 1;
            }
            if (moby->prev_seq != 4) {
                animate_2D5FA8(moby, 4, 0, 10);
            }
            moby->state = 1;
            d->i134 = scale_ticks(0xF0);
        }
        if (moby->pos.z < 5.0f) {
            DeleteMoby(moby);
            return;
        }
        break;
    case 0x63:
        if (mine_fall(moby, d->blk70) & 0x40) {
            moby->anim_speed = 0.0f;
            moby->state = 100;
            moby->collision = 0;
            d->s132 = 0x28;
            d->s130 = batalia_bombthrower_fade_ticks;
            spawn_moby_table_puff_pattern(moby);
            DeleteMoby(moby);
            return;
        }
        break;
    }
    effects_update_2D5FA8(moby, d->anim);
    d->i38 = 0;
}
