            *(float *)(m + 0x44) = random_angle_radians();
            *(float *)(m + 0x48) = random_angle_radians();
            vec[0] = random_float_between(-1.0f, 1.0f);
            vec[1] = random_float_between(-1.0f, 1.0f);
            vec[2] = random_float_between(-1.0f, 1.0f);
