/* Update function: switch on the state byte at +0x20. State 0 reads the table D_L08_001B0FB0[*data] (deleting
 * the moby if the index is -1), 1 steps along it, 2 falls under gravity and deletes the moby below z = 10.0
 * or on a hit. */
void update_path_following_moby(char *m) {
    float a[4];
    float b[4];
    char *d = ((char *)((Moby *)m)->pvars);
    char *pos = m + 0x10;
    int *t;
    qcopy(a, pos);
    t = (int *)batalia_path_table[*(int *)d];
    switch (((Moby *)m)->state) {
    case 0:
        if (*(int *)d == -1) {
            DeleteMoby(m);
            return;
        }
        {
            float l0 = FastVecDist((char *)t + 0x10, (char *)t + 0x20);
            FastVecDist((char *)t + 0x10, (char *)t + (*t << 4));
            *(float *)(d + 8) = *(float *)&batalia_path_mover_speed * g_frame_time / l0;
            *(float *)(d + 4) = *(float *)(d + 4) * (float)*t;
            *(float *)(d + 0xC) = randf_sym(0.0f, 5.0f);
        }
        m[0x20] = 1;
        ((Moby *)m)->update_dist = 0xFF;
    case 1: {
        float f;
        SamplePathAt(t, 1, m + 0x10, (float *)(m + 0x40), 0, *(float *)(d + 4));
        ((Moby *)m)->rot.y = ((Moby *)m)->rot.y * 0.5f;
        ((Moby *)m)->pos.z = ((Moby *)m)->pos.z + *(float *)(d + 0xC);
        *(float *)(d + 4) = *(float *)(d + 4) + *(float *)(d + 8);
        f = (float)*t;
        if (f < *(float *)(d + 4)) {
            *(float *)(d + 4) = *(float *)(d + 4) - f;
        }
        break;
    }
    case 2: {
        float c15 = 15.0f;
        float c10 = 10.0f;
        float dd;
        float g;
        char *v = d + 0x10;
        g = g_frame_time * 7.3303828f;
        *(float *)(d + 0x18) = *(float *)(d + 0x18) - g_frame_time_sq * c15;
        dd = FastAddRots(((Moby *)m)->rot.x, g);
        ((Moby *)m)->rot.x = ((Moby *)m)->rot.x + dd;
        ((Moby *)m)->rot.y = -fast_atan2(vec_length_xy(v), *(float *)(d + 0x18));
        FastVecAdd(pos, pos, v);
        if (((Moby *)m)->pos.z < c10) {
            DeleteMoby(m);
            return;
        }
        if (coll_sphere(1.25f, pos, 0, m)) {
            spawn_explosion(m, v, pos, 0.0f, 0.0f, 0x14, 0x28, 0x10, c10, 5.0f, 9.0f, 1.0f, -1, c15, 1, 1, -1, 0);
            DeleteMoby(m);
            return;
        }
        break;
    }
    default:
        break;
    }
    if (((Moby *)m)->pos.x < 4.0f || ((Moby *)m)->pos.y < 4.0f || ((Moby *)m)->pos.z < 4.0f) {
        *(int *)&((Moby *)m)->collision = 0;
    } else {
        *(int *)&((Moby *)m)->collision = *(int *)(*(char **)(m + 0x24) + 0x10);
    }
    if (MobyGetHitMessage(m, 0x10000, 0) != 0 && ((Moby *)m)->state != 2) {
        if (hero_current_state == 0x32 && gSkillPoints[0xC] == 0) {
            gSkillPoints[0xC] = 1;
            PlayBankSound(1, 0, 0);
            ShowBanner(0x53DB, -1);
        }
        FastVecSub(b, m + 0x10, a);
        qcopy(d + 0x10, b);
        *(float *)(d + 0x18) = *(float *)(d + 0x18) + (g_frame_time + g_frame_time);
        spawn_explosion(m, b, m + 0x10, 0.0f, 0.0f, 0x14, 0x28, 0x10, 10.0f, 5.0f, 9.0f, 1.0f, -1, 15.0f, 1, 1, -1, 0);
        m[0x20] = 2;
    }
    ((Moby *)m)->hit_slot = 0xFF;
    if (((Moby *)m)->visible != 0) {
        spawn_moby_motion_spark(m, (char *)a);
    }
}
